    this.$('chest-all').onclick = () => { g.chestTakeAll(key); this.showChest(key, true, wagon); }; if (wagon && this.$('wagon-ride')) this.$('wagon-ride').onclick = () => { this.closeModal(); g.driveWagon(wagon); };
