    if (showVillage) { let row = el.children[i]; if (!row) { row = document.createElement('div'); row.className = 'peer'; row.innerHTML = '<i><span>➜</span></i><div><b></b> <small></small></div>'; el.appendChild(row); } const dx = nv.village.cx - p.x, dz = nv.village.cz - p.z; const ang = Math.atan2(dx, -dz) + g.player.yaw; row.querySelector('i').style.background = '#e8d8a0'; row.querySelector('span').style.transform = `rotate(${(ang - Math.PI / 2) * 180 / Math.PI}deg)`; row.querySelector('b').textContent = nv.village.name; row.querySelector('small').textContent = Math.round(nv.dist) + ' blocks · village'; i++; }
    if (peers)
