    const eff = []; if (def.ph) eff.push(`pH ${def.ph > 0 ? 'up' : 'down'} ${Math.abs(def.ph).toFixed(1)}`); if (def.om) eff.push(`humus +${Math.round(def.om * 100)}%`); if (def.moisture) eff.push('holds moisture');
